+#[derive(Default)]
+pub struct StmtResult {
+    pub rows: Vec<Row>,
+    /// Row count from the CommandComplete tag (INSERT/UPDATE/DELETE/SELECT n).
+    pub affected: u64,
+}
+
+pub type GroupResult = Result<Vec<StmtResult>, PgError>;
