+    fn statements_have_matching_params() {
+        for (i, st) in STATEMENTS.iter().enumerate() {
+            let max = (1..=9).rev().find(|n| st.sql.contains(&format!("${n}"))).unwrap_or(0);
+            assert_eq!(max, st.params.len(), "s{i}: {}", st.sql);
+        }
+    }
+}

